import{_ as o}from"./chunks/thumb-10.CtKDnHZc.js";import{_ as e}from"./chunks/photo-10.nYi0PDyF.js";import{_ as r,H as a,f as l,i}from"./chunks/framework.Cvt1eIE0.js";const m=JSON.parse('{"title":"Roo Code 使用教程：VS Code Agent 模式与 Cline 生态对比","description":"","frontmatter":{"title":"Roo Code 使用教程：VS Code Agent 模式与 Cline 生态对比","date":"2026-05-23T00:00:00.000Z","category":"技术","tags":["AI","Roo Code","VS Code","教程"],"excerpt":"Roo Code（原 Roo Cline）VS Code 扩展：Code/Architect/Debug 模式、API 配置与和 Cline 的选型。"},"headers":[],"relativePath":"posts/技术/roo-code-tutorial.md","filePath":"posts/技术/roo-code-tutorial.md"}'),d={name:"posts/技术/roo-code-tutorial.md"};function n(s,t,c,h,g,p){return a(),l("div",null,[...t[0]||(t[0]=[i('<img src="'+o+'" alt="配图" class="article-banner" loading="lazy"><div class="figure wide"><img src="'+e+'" alt="随拍配图" loading="lazy"><p class="figure-caption">同一编辑器里，也可以切换不同的「工种」模式。</p></div><h1 id="roo-code-使用教程" tabindex="-1">Roo Code 使用教程 <a class="header-anchor" href="#roo-code-使用教程" aria-label="Permalink to &quot;Roo Code 使用教程&quot;">​</a></h1><p><a href="https://github.com/RooCodeInc/Roo-Code" target="_blank" rel="noreferrer">Roo Code</a>（前身为 <strong>Roo Cline</strong>，由 Cline 生态分支发展）是 VS Code 上的 <strong>AI 编程 Agent</strong> 扩展。与 <a href="/posts/技术/cline-vscode-agent-tutorial.html">Cline</a> 类似，通过自有 API Key 调用多厂商模型；差异在于 Roo Code 强调<strong>多角色模式</strong>（写代码 / 做架构 / 调试）与更细的自定义配置。</p><p>适合：留在 VS Code、希望<strong>比单一 Chat 更有分工</strong>、且愿意折腾 Provider 与模式的开发者。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>VS Code 扩展市场搜索 <strong>Roo Code</strong>（或 <strong>Roo Cline</strong>，以市场显示名为准）。</li><li>安装后侧边栏出现 Roo 图标，打开 <strong>Settings</strong>。</li><li>配置 <strong>API Provider</strong>（Anthropic、OpenAI、OpenRouter、Ollama 本地等）。</li><li>填入 API Key，选择默认模型。</li><li>（可选）安装推荐主题/图标仅为美观，非必须。</li></ol><h2 id="模式一览" tabindex="-1">模式一览 <a class="header-anchor" href="#模式一览" aria-label="Permalink to &quot;模式一览&quot;">​</a></h2><p>Roo Code 的核心是<strong>按任务切换模式</strong>（名称以当前版本 UI 为准）：</p><table tabindex="0"><thead><tr><th>模式</th><th>典型用途</th></tr></thead><tbody><tr><td><strong>Code</strong></td><td>实现功能、改 bug、写测试</td></tr><tr><td><strong>Architect</strong></td><td>方案设计、模块划分、ADR 草稿，少直接改代码</td></tr><tr><td><strong>Debug</strong></td><td>根据日志/堆栈推理根因，提出最小修复</td></tr><tr><td><strong>Ask</strong></td><td>只问不改，适合读代码</td></tr></tbody></table><p>实践建议：</p><ul><li>新功能先 <strong>Architect</strong> 出步骤与文件清单 → 再 <strong>Code</strong> 落地</li><li>线上问题用 <strong>Debug</strong>，避免 Agent 大范围重写</li></ul><h2 id="基本工作流" tabindex="-1">基本工作流 <a class="header-anchor" href="#基本工作流" aria-label="Permalink to &quot;基本工作流&quot;">​</a></h2><ol><li>在 Roo 面板选择模式（如 Code）。</li><li>用 <code>@</code> 引用文件或文件夹（如 <code>@src/services/</code>）。</li><li>描述任务与验收标准（测试命令、边界）。</li><li>审阅 diff，在终端执行 <code>npm test</code> / <code>flutter test</code>。</li><li>失败则切换 <strong>Debug</strong> 模式，粘贴完整报错继续迭代。</li></ol><h2 id="自定义与-roo-配置" tabindex="-1">自定义与 <code>.roo</code> 配置 <a class="header-anchor" href="#自定义与-roo-配置" aria-label="Permalink to &quot;自定义与 `.roo` 配置&quot;">​</a></h2><p>Roo Code 支持较丰富的自定义（具体文件名见官方文档），常见包括：</p><ul><li><strong>Custom Modes</strong>：为团队定义「只做 Review」「只写文档」等模式</li><li><strong>Rules / Instructions</strong>：编码规范、禁止路径</li><li><strong>MCP</strong>：挂载外部工具（文档检索、Issue 系统等）</li></ul><p>将「必须跑哪些检查」写进规则，比每次口头提醒更可靠。</p><h2 id="与-cline-如何二选一" tabindex="-1">与 Cline 如何二选一 <a class="header-anchor" href="#与-cline-如何二选一" aria-label="Permalink to &quot;与 Cline 如何二选一&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Roo Code</th><th>Cline</th></tr></thead><tbody><tr><td>来源</td><td>Cline 分支演进</td><td>主流开源主线</td></tr><tr><td>模式</td><td>多角色（Code/Architect/Debug）</td><td>Plan / Act</td></tr><tr><td>社区</td><td>活跃，功能迭代快</td><td>用户基数大</td></tr><tr><td>配置复杂度</td><td>偏高</td><td>相对直接</td></tr></tbody></table><p><strong>团队统一选一个即可</strong>，避免同一仓库两套 Agent 配置分叉。个人可先各试用一个下午，看哪个 diff 更贴项目风格。</p><h2 id="成本与模型" tabindex="-1">成本与模型 <a class="header-anchor" href="#成本与模型" aria-label="Permalink to &quot;成本与模型&quot;">​</a></h2><ul><li>自带 API Key：按提供商计费，适合控成本。</li><li>本地 <strong>Ollama</strong>：适合离线试验，复杂任务需选对模型体积。</li><li>国产模型：通过 OpenRouter 或兼容 <code>base_url</code> 接入（注意合规）。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：和 Cline 配置能迁移吗？</strong><br> A：部分 Provider 设置类似，但规则文件格式不一定兼容，需按 Roo 文档迁移。</p><p><strong>Q：Roo 会自动跑终端命令吗？</strong><br> A：会提议执行；生产环境关闭盲目 auto-approve，对删除与网络命令人工确认。</p><p><strong>Q：还值得学 Cline 吗？</strong><br> A：原理相通；会 Roo 再学 Cline 很快。招聘/协作看团队标准工具即可。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/posts/技术/cline-vscode-agent-tutorial.html">Cline 使用教程</a></li><li><a href="/posts/技术/ai-coding-tools-index.html">AI 编程工具教程索引</a></li><li><a href="/posts/收藏/appark-cc-switch-download-tutorial.html">CC Switch 多 Agent 配置</a></li></ul><hr><p><em>模式名称与配置项以 Roo Code GitHub 文档为准。</em></p>',31)])])}const f=r(d,[["render",n]]);export{m as __pageData,f as default};
